-- Original retained tournament hands interrupted by the 2026-10-06
-- patterned-identity force drain. Cash custody and retired profiles are untouched.
-- Installed source is inert without a current native successor lease.
BEGIN;
SET LOCAL lock_timeout='3s';
SET LOCAL statement_timeout='60s';

DO $preimage$
BEGIN
 IF md5(pg_get_functiondef('public.fn_ca_resume_hand_submission(uuid,text,uuid)'::regprocedure))
    IS DISTINCT FROM '9ca8d457e08fd60a140bacddd605039b' THEN
  RAISE EXCEPTION 'RETIREMENT_ORIGINAL_RESUME_PREIMAGE_CHANGED' USING ERRCODE='55000';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid='public.fn_ca_resume_hand_submission(uuid,text,uuid)'::regprocedure
   AND proowner='postgres'::regrole AND prosecdef
   AND proconfig=ARRAY['search_path=pg_catalog, public']
   AND proacl::text='{postgres=X/postgres,service_role=X/postgres}') THEN
  RAISE EXCEPTION 'RETIREMENT_ORIGINAL_RESUME_SECURITY_CHANGED' USING ERRCODE='55000';
 END IF;
 IF to_regclass('smarter_private.patterned_identity_retirements') IS NULL THEN
  RAISE EXCEPTION 'RETIREMENT_ORIGINAL_COHORT_MISSING' USING ERRCODE='55000';
 END IF;
END $preimage$;

CREATE TABLE smarter_private.retirement_original_hand_qualification(
 submission_id uuid PRIMARY KEY, request_hash text NOT NULL,
 table_id uuid NOT NULL, tournament_id uuid NOT NULL, hand_number bigint NOT NULL,
 expected jsonb NOT NULL, UNIQUE(table_id,hand_number));
CREATE TABLE smarter_private.retirement_original_hand_restorations(
 submission_id uuid PRIMARY KEY REFERENCES smarter_private.retirement_original_hand_qualification,
 original_generation uuid NOT NULL, successor_generation uuid NOT NULL,
 instance_id text NOT NULL, request_hash text NOT NULL, qualification_hash text NOT NULL,
 transaction_id bigint NOT NULL, restored_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 restored_players integer NOT NULL CHECK(restored_players>0));
REVOKE ALL ON smarter_private.retirement_original_hand_qualification,
 smarter_private.retirement_original_hand_restorations FROM PUBLIC,anon,authenticated,service_role;
ALTER TABLE smarter_private.retirement_original_hand_qualification OWNER TO postgres;
ALTER TABLE smarter_private.retirement_original_hand_restorations OWNER TO postgres;
CREATE TRIGGER retirement_original_qualification_immutable
 BEFORE UPDATE OR DELETE ON smarter_private.retirement_original_hand_qualification
 FOR EACH ROW EXECUTE FUNCTION smarter_private.hand_submission_immutable();
CREATE TRIGGER retirement_original_qualification_no_truncate
 BEFORE TRUNCATE ON smarter_private.retirement_original_hand_qualification
 FOR EACH STATEMENT EXECUTE FUNCTION smarter_private.hand_submission_immutable();
CREATE TRIGGER retirement_original_restoration_immutable
 BEFORE UPDATE OR DELETE ON smarter_private.retirement_original_hand_restorations
 FOR EACH ROW EXECUTE FUNCTION smarter_private.hand_submission_immutable();
CREATE TRIGGER retirement_original_restoration_no_truncate
 BEFORE TRUNCATE ON smarter_private.retirement_original_hand_restorations
 FOR EACH STATEMENT EXECUTE FUNCTION smarter_private.hand_submission_immutable();
